'use client';
import {fieldLabel,formatValue,displayFields,recordTitle} from '../../lib/admin/presentation.mjs';
import FloatingPopover from './FloatingPopover';
import React,{useEffect,useState,useMemo,useRef} from 'react';
import {Search,ChevronDown,ChevronLeft,ChevronRight,ArrowUpRight,ArrowDownLeft,Plus,MoreHorizontal,X,Check,Menu,PanelLeftClose,PanelLeftOpen,Sun,Moon,Bell,Download,RefreshCw,Filter,SlidersHorizontal,ArrowUpDown,ArrowRight,Leaf,ExternalLink,CalendarDays,Clock,Users,Heart,Flag,ShieldCheck,CheckCircle2,AlertCircle,Info,LogOut,Link2,Send,Trash2,Eye,Copy,HelpCircle,LoaderCircle,FileText,LockKeyhole,Mail,Settings,Activity,CheckCheck,ChartNoAxesCombined,BookOpen,Headphones} from 'lucide-react';
import {modules,moduleByKey,roleLabels,actionLabels,statuses,text,date,datetime,type Row,type Module,type Role,type Field} from '../../lib/admin/modules';
